package ro.boardgamecafe.core.domain.billing;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;
import jakarta.persistence.*;
import ro.boardgamecafe.core.domain.table.SessionParticipant;
import ro.boardgamecafe.core.domain.table.TableSession;

/**
 * One attempt to pay the whole bill. The amount is always computed by the server. The idempotency key,
 * generated by the client per attempt, makes a retried request return the original result instead of
 * charging again.
 */
@Entity
@Table(name = "payments")
public class Payment {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "session_id", nullable = false)
    private TableSession session;
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "initiated_by_id", nullable = false)
    private SessionParticipant initiatedBy;
    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal amount;
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private PaymentStatus status;
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private PaymentMethod method;
    @Column(name = "idempotency_key", nullable = false, unique = true)
    private UUID idempotencyKey;
    @Column(name = "created_at", nullable = false)
    private Instant createdAt;
    @Column(name = "completed_at")
    private Instant completedAt;
    @Column(name = "failure_reason", columnDefinition = "TEXT")
    private String failureReason;

    protected Payment() {
    }

    private Payment(SessionParticipant initiatedBy, BigDecimal amount, UUID idempotencyKey) {
        if (initiatedBy == null || idempotencyKey == null) throw new IllegalArgumentException("Payer and key are required.");
        if (amount == null || amount.signum() < 0) throw new IllegalArgumentException("Amount must be zero or positive.");
        this.session = initiatedBy.getSession();
        this.initiatedBy = initiatedBy;
        this.amount = amount;
        this.method = PaymentMethod.SIMULATED;
        this.idempotencyKey = idempotencyKey;
        this.createdAt = Instant.now();
        this.status = PaymentStatus.PENDING;
    }

    public static Payment succeeded(SessionParticipant payer, BigDecimal amount, UUID idempotencyKey) {
        Payment payment = new Payment(payer, amount, idempotencyKey);
        payment.status = PaymentStatus.SUCCEEDED;
        payment.completedAt = payment.createdAt;
        return payment;
    }

    public static Payment failed(SessionParticipant payer, BigDecimal amount, UUID idempotencyKey, String reason) {
        Payment payment = new Payment(payer, amount, idempotencyKey);
        payment.status = PaymentStatus.FAILED;
        payment.completedAt = payment.createdAt;
        payment.failureReason = reason;
        return payment;
    }

    public Long getId() { return id; }
    public TableSession getSession() { return session; }
    public SessionParticipant getInitiatedBy() { return initiatedBy; }
    public BigDecimal getAmount() { return amount; }
    public PaymentStatus getStatus() { return status; }
    public PaymentMethod getMethod() { return method; }
    public UUID getIdempotencyKey() { return idempotencyKey; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getCompletedAt() { return completedAt; }
    public String getFailureReason() { return failureReason; }
}
